require __DIR__.'/../app/bootstrap.php';require __DIR__.'/../app/view.php';page_start('Sources','sources.php');heading('TRANSPARENCE','La qualité commence à la source.','État des flux et fraîcheur des données. Un échec de collecte ne supprime pas les articles déjà enregistrés.');
?><p>Collecte en retard : aucun succès depuis une heure. Aucune publication récente : aucun article daté des sept derniers jours, ce qui peut être normal pour une source peu active.</p><div class="source-grid"><?php foreach(run('SELECT s.*,COUNT(a.id) AS count,MAX(a.published) AS last_article FROM sources s LEFT JOIN articles a ON a.source_id=s.id GROUP BY s.id ORDER BY s.name')->fetchAll() as $s):[$label,$class]=source_health($s);?><article class="panel source-card"><div class="card-meta"><span class="badge"><?=e($s['category'])?></span><span class="badge <?=e($class)?>"><?=e($label)?></span></div><h2><?=e($s['name'])?></h2><p><?=$s['count']?> articles conservés</p><p class="muted">Dernier succès : <?=e(when($s['success_at']?(int)$s['success_at']:null))?></p><p class="muted">Dernière publication : <?=e(when($s['last_article']?(int)$s['last_article']:null))?></p><?php if($s['error']):?><p class="error-text"><?=e($s['error'])?></p><?php endif ?><a href="<?=e($s['url'])?>" target="_blank" rel="noopener noreferrer">Voir le flux ↗</a></article><?php endforeach ?></div><?php page_end();
